#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
int main(void)
{
    int_least32_t temperature = -12;
    uint_least32_t device_id = 42000U;
    printf("temperature=%" PRIdLEAST32 "\n", temperature);
    printf("device_id=%" PRIuLEAST32 "\n", device_id);
    return 0;
