#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
int main(void)
{
    int_least32_t value = 0;
    if (scanf("%" SCNdLEAST32, &value) != 1) {
        fputs("Invalid integer input\n", stderr);
        return 1;
    }
    printf("value=%" PRIdLEAST32 "\n", value);
    return 0;
}
